// CanvasServiceHandler is an implementation of the woohaa.canvas.v1.CanvasService service.
type CanvasServiceHandler interface {
	// 创建一张画布，调用者成为作者。canvas_id 由服务端分配。
	CreateCanvas(context.Context, *connect.Request[v1.CreateCanvasRequest]) (*connect.Response[v1.CreateCanvasResponse], error)
	GetCanvas(context.Context, *connect.Request[v1.GetCanvasRequest]) (*connect.Response[v1.GetCanvasResponse], error)
	RenameCanvas(context.Context, *connect.Request[v1.RenameCanvasRequest]) (*connect.Response[v1.RenameCanvasResponse], error)
	// 删除画布（墓碑）。作者与管理员都能删；删除后访问返回 410，不会自动重建。
	DeleteCanvas(context.Context, *connect.Request[v1.DeleteCanvasRequest]) (*connect.Response[v1.DeleteCanvasResponse], error)
	// 我的画布（作者或协作者）。
	ListMyCanvases(context.Context, *connect.Request[v1.ListMyCanvasesRequest]) (*connect.Response[v1.ListMyCanvasesResponse], error)
	// 部署管理员的画布清单。非管理员一律拒绝（不是返回空列表）。
	AdminListCanvases(context.Context, *connect.Request[v1.AdminListCanvasesRequest]) (*connect.Response[v1.AdminListCanvasesResponse], error)
	// 管理端：记录与快照清单（只有元数据）。用于回答"这张画布由哪些记录组成、
	// 快照覆盖到哪、最近有没有异常增长"。非部署管理员拒绝。
	AdminListCanvasRecords(context.Context, *connect.Request[v1.AdminListCanvasRecordsRequest]) (*connect.Response[v1.AdminListCanvasRecordsResponse], error)
	// 管理端：按 seq 升序读取记录字节，用于多版本解码与对比。服务端不解析 Yjs，
	// 也不在这里替调用方合并；调用方按顺序把 update 应用到一个文档上即可重建版本。
	// 字节预算按整条记录截断，因此返回的每条都是完整可应用的 update。
	AdminReadCanvasRecords(context.Context, *connect.Request[v1.AdminReadCanvasRecordsRequest]) (*connect.Response[v1.AdminReadCanvasRecordsResponse], error)
	// 协作者管理。作者与管理员能读写；协作者通过 GetCanvas 读自己的角色。
	ListCanvasMembers(context.Context, *connect.Request[v1.ListCanvasMembersRequest]) (*connect.Response[v1.ListCanvasMembersResponse], error)
	UpsertCanvasMember(context.Context, *connect.Request[v1.UpsertCanvasMemberRequest]) (*connect.Response[v1.UpsertCanvasMemberResponse], error)
	RemoveCanvasMember(context.Context, *connect.Request[v1.RemoveCanvasMemberRequest]) (*connect.Response[v1.RemoveCanvasMemberResponse], error)
	TransferCanvas(context.Context, *connect.Request[v1.TransferCanvasRequest]) (*connect.Response[v1.TransferCanvasResponse], error)
	// 协作邀请。创建/撤销走管理动作（作者或部署管理员），接受由持有链接的已认证主体完成。
	CreateCanvasInvite(context.Context, *connect.Request[v1.CreateCanvasInviteRequest]) (*connect.Response[v1.CreateCanvasInviteResponse], error)
	ListCanvasInvites(context.Context, *connect.Request[v1.ListCanvasInvitesRequest]) (*connect.Response[v1.ListCanvasInvitesResponse], error)
	RevokeCanvasInvite(context.Context, *connect.Request[v1.RevokeCanvasInviteRequest]) (*connect.Response[v1.RevokeCanvasInviteResponse], error)
	AcceptCanvasInvite(context.Context, *connect.Request[v1.AcceptCanvasInviteRequest]) (*connect.Response[v1.AcceptCanvasInviteResponse], error)
	GetCanvasShare(context.Context, *connect.Request[v1.GetCanvasShareRequest]) (*connect.Response[v1.GetCanvasShareResponse], error)
	UpdateCanvasShare(context.Context, *connect.Request[v1.UpdateCanvasShareRequest]) (*connect.Response[v1.UpdateCanvasShareResponse], error)
	// 立即把该画布的 update 合并成一份快照（平时由服务端按阈值定期执行）。
	// 这是运维动作，只有部署管理员能做：画布级 admin 不再能触发。
	CompactCanvas(context.Context, *connect.Request[v1.CompactCanvasRequest]) (*connect.Response[v1.CompactCanvasResponse], error)
	// 单张画布的存储统计。作者、协作者与管理员都能看。
	GetCanvasStats(context.Context, *connect.Request[v1.GetCanvasStatsRequest]) (*connect.Response[v1.GetCanvasStatsResponse], error)
	// 兼容别名：等价于 AdminListCanvases(include_deleted=false, include_stats=true)。
	ListCanvases(context.Context, *connect.Request[v1.ListCanvasesRequest]) (*connect.Response[v1.ListCanvasesResponse], error)
}

